pragma solidity 0.6.12; pragma experimental ABIEncoderV2; library SafeMathUpgradeable { function tryAdd(uint256 a, uint256 b) internal pure returns (bool, uint256) { uint256 c = a + b; if (c < a) return (false, 0); return (true, c); } function trySub(uint256 a, uint256 b) internal pure returns (bool, uint256) { if (b > a) return (false, 0); return (true, a - b); } function tryMul(uint256 a, uint256 b) internal pure returns (bool, uint256) { if (a == 0) return (true, 0); uint256 c = a * b; if (c / a != b) return (false, 0); return (true, c); } function tryDiv(uint256 a, uint256 b) internal pure returns (bool, uint256) { if (b == 0) return (false, 0); return (true, a / b); } function tryMod(uint256 a, uint256 b) internal pure returns (bool, uint256) { if (b == 0) return (false, 0); return (true, a % b); } function add(uint256 a, uint256 b) internal pure returns (uint256) { uint256 c = a + b; require(c >= a, "SafeMath: addition overflow"); return c; } function sub(uint256 a, uint256 b) internal pure returns (uint256) { require(b <= a, "SafeMath: subtraction overflow"); return a - b; } function mul(uint256 a, uint256 b) internal pure returns (uint256) { if (a == 0) return 0; uint256 c = a * b; require(c / a == b, "SafeMath: multiplication overflow"); return c; } function div(uint256 a, uint256 b) internal pure returns (uint256) { require(b > 0, "SafeMath: division by zero"); return a / b; } function mod(uint256 a, uint256 b) internal pure returns (uint256) { require(b > 0, "SafeMath: modulo by zero"); return a % b; } function sub( uint256 a, uint256 b, string memory errorMessage ) internal pure returns (uint256) { require(b <= a, errorMessage); return a - b; } function div( uint256 a, uint256 b, string memory errorMessage ) internal pure returns (uint256) { require(b > 0, errorMessage); return a / b; } function mod( uint256 a, uint256 b, string memory errorMessage ) internal pure returns (uint256) { require(b > 0, errorMessage); return a % b; } } library AddressUpgradeable { function isContract(address account) internal view returns (bool) { uint256 size; assembly { size := extcodesize(account) } return size > 0; } function sendValue(address payable recipient, uint256 amount) internal { require(address(this).balance >= amount, "Address: insufficient balance"); (bool success, ) = recipient.call{ value: amount }(""); require(success, "Address: unable to send value, recipient may have reverted"); } function functionCall(address target, bytes memory data) internal returns (bytes memory) { return functionCall(target, data, "Address: low-level call failed"); } function functionCall( address target, bytes memory data, string memory errorMessage ) internal returns (bytes memory) { return functionCallWithValue(target, data, 0, errorMessage); } function functionCallWithValue( address target, bytes memory data, uint256 value ) internal returns (bytes memory) { return functionCallWithValue(target, data, value, "Address: low-level call with value failed"); } function functionCallWithValue( address target, bytes memory data, uint256 value, string memory errorMessage ) internal returns (bytes memory) { require(address(this).balance >= value, "Address: insufficient balance for call"); require(isContract(target), "Address: call to non-contract"); (bool success, bytes memory returndata) = target.call{ value: value }(data); return _verifyCallResult(success, returndata, errorMessage); } function functionStaticCall(address target, bytes memory data) internal view returns (bytes memory) { return functionStaticCall(target, data, "Address: low-level static call failed"); } function functionStaticCall( address target, bytes memory data, string memory errorMessage ) internal view returns (bytes memory) { require(isContract(target), "Address: static call to non-contract"); (bool success, bytes memory returndata) = target.staticcall(data); return _verifyCallResult(success, returndata, errorMessage); } function _verifyCallResult( bool success, bytes memory returndata, string memory errorMessage ) private pure returns (bytes memory) { if (success) { return returndata; } else { if (returndata.length > 0) { assembly { let returndata_size := mload(returndata) revert(add(32, returndata), returndata_size) } } else { revert(errorMessage); } } } } abstract contract Initializable { bool private _initialized; bool private _initializing; modifier initializer() { require(_initializing || _isConstructor() || !_initialized, "Initializable: contract is already initialized"); bool isTopLevelCall = !_initializing; if (isTopLevelCall) { _initializing = true; _initialized = true; } _; if (isTopLevelCall) { _initializing = false; } } function _isConstructor() private view returns (bool) { return !AddressUpgradeable.isContract(address(this)); } } abstract contract ContextUpgradeable is Initializable { function __Context_init() internal initializer { __Context_init_unchained(); } function __Context_init_unchained() internal initializer {} function _msgSender() internal view virtual returns (address payable) { return msg.sender; } function _msgData() internal view virtual returns (bytes memory) { this; return msg.data; } uint256[50] private __gap; } abstract contract OwnableUpgradeable is Initializable, ContextUpgradeable { address private _owner; event OwnershipTransferred(address indexed previousOwner, address indexed newOwner); function __Ownable_init() internal initializer { __Context_init_unchained(); __Ownable_init_unchained(); } function __Ownable_init_unchained() internal initializer { address msgSender = _msgSender(); _owner = msgSender; emit OwnershipTransferred(address(0), msgSender); } function owner() public view virtual returns (address) { return _owner; } modifier onlyOwner() { require(owner() == _msgSender(), "Ownable: caller is not the owner"); _; } function renounceOwnership() public virtual onlyOwner { emit OwnershipTransferred(_owner, address(0)); _owner = address(0); } function transferOwnership(address newOwner) public virtual onlyOwner { require(newOwner != address(0), "Ownable: new owner is the zero address"); emit OwnershipTransferred(_owner, newOwner); _owner = newOwner; } uint256[49] private __gap; } interface ISafemoon { function totalSupply() external view returns (uint256); function balanceOf(address account) external view returns (uint256); function transfer(address recipient, uint256 amount) external returns (bool); function allowance(address owner, address spender) external view returns (uint256); function approve(address spender, uint256 amount) external returns (bool); function transferFrom( address sender, address recipient, uint256 amount ) external returns (bool); function migrate(address account, uint256 amount) external; function isMigrationStarted() external view returns (bool); event Transfer(address indexed from, address indexed to, uint256 value); event Approval(address indexed owner, address indexed spender, uint256 value); } interface IUniswapV2Factory { event PairCreated(address indexed token0, address indexed token1, address pair, uint256); function createPair( address tokenA, address tokenB, address to ) external returns (address pair); } interface IUniswapV2Router01 { function factory() external pure returns (address); function routerTrade() external pure returns (address); function WETH() external pure returns (address); function addLiquidityETH( address token, uint256 amountTokenDesired, uint256 amountTokenMin, uint256 amountETHMin, address to, uint256 deadline ) external payable returns ( uint256 amountToken, uint256 amountETH, uint256 liquidity ); } interface IUniswapV2Router02 is IUniswapV2Router01 { } interface ISafeSwapTradeRouter { struct Trade { uint256 amountIn; uint256 amountOut; address[] path; address payable to; uint256 deadline; } function setRouter(address _router) external; function setFeePercent(uint256 _feePercent) external; function sePercent(uint256 _percent) external; function addFfsWhitelist(address _wl) external; function removeFfsWhitelist(address _wl) external; function setFeeJar(address _feeJar) external; function swapExactTokensForETHAndFeeAmount(Trade calldata trade) external payable; function swapTokensForExactETHAndFeeAmount(Trade calldata trade) external payable; function swapExactETHForTokensWithFeeAmount(Trade calldata trade, uint256 _feeAmount) external payable; function swapETHForExactTokensWithFeeAmount(Trade calldata trade, uint256 _feeAmount) external payable; function swapExactTokensForTokensWithFeeAmount(Trade calldata trade) external payable; function swapTokensForExactTokensWithFeeAmount(Trade calldata trade) external payable; function getSwapFee( uint256 amountIn, uint256 _amountOut, address tokenA, address tokenB ) external view returns (uint256 _fee); function getSwapFees(uint256 amountIn, address[] memory path) external view returns (uint256 _fees); } contract Safemoon is ISafemoon, Initializable, ContextUpgradeable, OwnableUpgradeable { using SafeMathUpgradeable for uint256; using AddressUpgradeable for address; struct FeeTier { uint256 ecoSystemFee; uint256 liquidityFee; uint256 taxFee; uint256 ownerFee; uint256 burnFee; address ecoSystem; address owner; } struct FeeValues { uint256 rAmount; uint256 rTransferAmount; uint256 rFee; uint256 tTransferAmount; uint256 tEchoSystem; uint256 tLiquidity; uint256 tFee; uint256 tOwner; uint256 tBurn; } struct tFeeValues { uint256 tTransferAmount; uint256 tEchoSystem; uint256 tLiquidity; uint256 tFee; uint256 tOwner; uint256 tBurn; } mapping(address => uint256) private _rOwned; mapping(address => uint256) private _tOwned; mapping(address => mapping(address => uint256)) private _allowances; mapping(address => bool) private _isExcludedFromFee; mapping(address => bool) private _isExcluded; mapping(address => bool) private _isBlacklisted; mapping(address => uint256) private _accountsTier; address[] private _excluded; uint256 private constant MAX = ~uint256(0); uint256 private _tTotal; uint256 private _rTotal; uint256 private _tFeeTotal; uint256 private _maxFee; string private _name; string private _symbol; uint8 private _decimals; FeeTier public _defaultFees; FeeTier private _previousFees; FeeTier private _emptyFees; FeeTier[] private feeTiers; IUniswapV2Router02 public uniswapV2Router; address public uniswapV2Pair; address public WBNB; address private migration; address private _initializerAccount; address public _burnAddress; bool inSwapAndLiquify; bool public swapAndLiquifyEnabled; uint256 public _maxTxAmount; uint256 private numTokensSellToAddToLiquidity; bool private _upgraded; event MinTokensBeforeSwapUpdated(uint256 minTokensBeforeSwap); modifier lockTheSwap() { inSwapAndLiquify = true; _; inSwapAndLiquify = false; } modifier lockUpgrade() { require(!_upgraded, "Safemoon: Already upgraded"); _; _upgraded = true; } modifier checkTierIndex(uint256 _index) { require(feeTiers.length > _index, "Safemoon: Invalid tier index"); _; } modifier preventBlacklisted(address _account, string memory errorMsg) { require(!_isBlacklisted[_account], errorMsg); _; } modifier isRouter(address _sender) { { uint32 size; assembly { size := extcodesize(_sender) } if (size > 0) { uint256 senderTier = _accountsTier[_sender]; if (senderTier == 0) { IUniswapV2Router02 _routerCheck = IUniswapV2Router02(_sender); try _routerCheck.factory() returns (address factory) { _accountsTier[_sender] = 1; } catch {} } } } _; } uint256 public numTokensToCollectBNB; uint256 public numOfBnbToSwapAndEvolve; bool inSwapAndEvolve; bool public swapAndEvolveEnabled; uint256 private _rTotalExcluded; uint256 private _tTotalExcluded; mapping(address => bool) public listIgnoreCollectBNBAddresses; address public bridgeBurnAddress; mapping(address => bool) public whitelistMint; event SwapAndEvolveEnabledUpdated(bool enabled); event SwapAndEvolve(uint256 bnbSwapped, uint256 tokenReceived, uint256 bnbIntoLiquidity); event AddIgnoreCollectBNBAddress(address ignoreAddress); event RemoveIgnoreCollectBNBAddress(address ignoreAddress); modifier only