lic view override returns (uint256) { return _allowances[owner][spender]; } function approve(address spender, uint256 amount) public override returns (bool) { _approve(_msgSender(), spender, amount); return true; } function transferFrom( address sender, address recipient, uint256 amount ) public override returns (bool) { _transfer(sender, recipient, amount); _approve( sender, _msgSender(), _allowances[sender][_msgSender()].sub(amount, "BEP20: transfer amount exceeds allowance") ); return true; } function increaseAllowance(address spender, uint256 addedValue) public virtual returns (bool) { _approve(_msgSender(), spender, _allowances[_msgSender()][spender].add(addedValue)); return true; } function decreaseAllowance(address spender, uint256 subtractedValue) public virtual returns (bool) { _approve( _msgSender(), spender, _allowances[_msgSender()][spender].sub(subtractedValue, "BEP20: decreased allowance below zero") ); return true; } function isExcludedFromReward(address account) public view returns (bool) { return _isExcluded[account]; } function totalFees() public view returns (uint256) { return _tFeeTotal; } function reflectionFromTokenInTiers( uint256 tAmount, uint256 _tierIndex, bool deductTransferFee ) public view returns (uint256) { require(tAmount <= _tTotal, "Amount must be less than supply"); if (!deductTransferFee) { FeeValues memory _values = _getValues(tAmount, _tierIndex); return _values.rAmount; } else { FeeValues memory _values = _getValues(tAmount, _tierIndex); return _values.rTransferAmount; } } function reflectionFromToken(uint256 tAmount, bool deductTransferFee) public view returns (uint256) { return reflectionFromTokenInTiers(tAmount, 0, deductTransferFee); } function tokenFromReflection(uint256 rAmount) public view returns (uint256) { require(rAmount <= _rTotal, "Amount must be less than total reflections"); uint256 currentRate = _getRate(); return rAmount.div(currentRate); } function excludeFromReward(address account) public onlyOwner { if (_rOwned[account] > 0) { _tOwned[account] = tokenFromReflection(_rOwned[account]); _tTotalExcluded = _tTotalExcluded.add(_tOwned[account]); _rTotalExcluded = _rTotalExcluded.add(_rOwned[account]); } _isExcluded[account] = true; _excluded.push(account); } function includeInReward(address account) external onlyOwner { for (uint256 i = 0; i < _excluded.length; i++) { if (_excluded[i] == account) { _excluded[i] = _excluded[_excluded.length - 1]; _tTotalExcluded = _tTotalExcluded.sub(_tOwned[account]); _rTotalExcluded = _rTotalExcluded.sub(_rOwned[account]); _tOwned[account] = 0; _isExcluded[account] = false; _excluded.pop(); break; } } } function excludeFromFee(address account) public onlyOwner { _isExcludedFromFee[account] = true; } function includeInFee(address account) public onlyOwner { _isExcludedFromFee[account] = false; } function whitelistAddress(address _account, uint256 _tierIndex) public onlyOwner checkTierIndex(_tierIndex) preventBlacklisted(_account, "Safemoon: Selected account is in blacklist") { require(_account != address(0), "Safemoon: Invalid address"); _accountsTier[_account] = _tierIndex; } function excludeWhitelistedAddress(address _account) public onlyOwner { require(_account != address(0), "Safemoon: Invalid address"); require(_accountsTier[_account] > 0, "Safemoon: Account is not in whitelist"); _accountsTier[_account] = 0; } function accountTier(address _account) public view returns (FeeTier memory) { return feeTiers[_accountsTier[_account]]; } function isWhitelisted(address _account) public view returns (bool) { return _accountsTier[_account] > 0; } function checkFees(FeeTier memory _tier) internal view returns (FeeTier memory) { uint256 _fees = _tier.ecoSystemFee.add(_tier.liquidityFee).add(_tier.taxFee).add(_tier.ownerFee).add( _tier.burnFee ); require(_fees <= _maxFee, "Safemoon: Fees exceeded max limitation"); return _tier; } function checkFeesChanged( FeeTier memory _tier, uint256 _oldFee, uint256 _newFee ) internal view { uint256 _fees = _tier .ecoSystemFee .add(_tier.liquidityFee) .add(_tier.taxFee) .add(_tier.ownerFee) .add(_tier.burnFee) .sub(_oldFee) .add(_newFee); require(_fees <= _maxFee, "Safemoon: Fees exceeded max limitation"); } function setEcoSystemFeePercent(uint256 _tierIndex, uint256 _ecoSystemFee) external onlyOwner checkTierIndex(_tierIndex) { FeeTier memory tier = feeTiers[_tierIndex]; checkFeesChanged(tier, tier.ecoSystemFee, _ecoSystemFee); feeTiers[_tierIndex].ecoSystemFee = _ecoSystemFee; if (_tierIndex == 0) { _defaultFees.ecoSystemFee = _ecoSystemFee; } } function setLiquidityFeePercent(uint256 _tierIndex, uint256 _liquidityFee) external onlyOwner checkTierIndex(_tierIndex) { FeeTier memory tier = feeTiers[_tierIndex]; checkFeesChanged(tier, tier.liquidityFee, _liquidityFee); feeTiers[_tierIndex].liquidityFee = _liquidityFee; if (_tierIndex == 0) { _defaultFees.liquidityFee = _liquidityFee; } } function setTaxFeePercent(uint256 _tierIndex, uint256 _taxFee) external onlyOwner checkTierIndex(_tierIndex) { FeeTier memory tier = feeTiers[_tierIndex]; checkFeesChanged(tier, tier.taxFee, _taxFee); feeTiers[_tierIndex].taxFee = _taxFee; if (_tierIndex == 0) { _defaultFees.taxFee = _taxFee; } } function setOwnerFeePercent(uint256 _tierIndex, uint256 _ownerFee) external onlyOwner checkTierIndex(_tierIndex) { FeeTier memory tier = feeTiers[_tierIndex]; checkFeesChanged(tier, tier.ownerFee, _ownerFee); feeTiers[_tierIndex].ownerFee = _ownerFee; if (_tierIndex == 0) { _defaultFees.ownerFee = _ownerFee; } } function setBurnFeePercent(uint256 _tierIndex, uint256 _burnFee) external onlyOwner checkTierIndex(_tierIndex) { FeeTier memory tier = feeTiers[_tierIndex]; checkFeesChanged(tier, tier.burnFee, _burnFee); feeTiers[_tierIndex].burnFee = _burnFee; if (_tierIndex == 0) { _defaultFees.burnFee = _burnFee; } } function setEcoSystemFeeAddress(uint256 _tierIndex, address _ecoSystem) external onlyOwner checkTierIndex(_tierIndex) { require(_ecoSystem != address(0), "Safemoon: Address Zero is not allowed"); excludeFromReward(_ecoSystem); feeTiers[_tierIndex].ecoSystem = _ecoSystem; if (_tierIndex == 0) { _defaultFees.ecoSystem = _ecoSystem; } } function setOwnerFeeAddress(uint256 _tierIndex, address _owner) external onlyOwner checkTierIndex(_tierIndex) { require(_owner != address(0), "Safemoon: Address Zero is not allowed"); excludeFromReward(_owner); feeTiers[_tierIndex].owner = _owner; if (_tierIndex == 0) { _defaultFees.owner = _owner; } } function addTier( uint256 _ecoSystemFee, uint256 _liquidityFee, uint256 _taxFee, uint256 _ownerFee, uint256 _burnFee, address _ecoSystem, address _owner ) public onlyOwner { _addTier(_ecoSystemFee, _liquidityFee, _taxFee, _ownerFee, _burnFee, _ecoSystem, _owner); } function _addTier( uint256 _ecoSystemFee, uint256 _liquidityFee, uint256 _taxFee, uint256 _ownerFee, uint256 _burnFee, address _ecoSystem, address _owner ) internal returns (FeeTier memory) { FeeTier memory _newTier = checkFees( FeeTier(_ecoSystemFee, _liquidityFee, _taxFee, _ownerFee, _burnFee, _ecoSystem, _owner) ); excludeFromReward(_ecoSystem); excludeFromReward(_owner); feeTiers.push(_newTier); return _newTier; } function feeTier(uint256 _tierIndex) public view checkTierIndex(_tierIndex) returns (FeeTier memory) { return feeTiers[_tierIndex]; } function blacklistAddress(address account) public onlyOwner { _isBlacklisted[account] = true; _accountsTier[account] = 0; } function unBlacklistAddress(address account) public onlyOwner { _isBlacklisted[account] = false; } function updateRouterAndPair(address _uniswapV2Router, address _uniswapV2Pair) public onlyOwner { uniswapV2Router = IUniswapV2Router02(_uniswapV2Router); uniswapV2Pair = _uniswapV2Pair; WBNB = uniswapV2Router.WETH(); } function setDefaultSettings() external onlyOwner { swapAndLiquifyEnabled = false; swapAndEvolveEnabled = true; } function setMaxTxPercent(uint256 maxTxPercent) external onlyOwner { _maxTxAmount = _tTotal.mul(maxTxPercent).div(10**4); } function setSwapAndEvolveEnabled(bool _enabled) pu